from typing import List
class Solution:
    def closetTarget(self, words: List[str], target: str, startIndex: int) -> int:
        n = len(words)
        best = float('inf')
        for i in range(n):
            if words[i] == target:
                d = abs(startIndex - i)
                d = min(d, n - d)
                if d < best:
                    best = d
        return -1 if best == float('inf') else best

